head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vMktactCd = '202'; // 채권시장조치구분코드
scwin.pBndApplId = '';
scwin.vBndListProcsTpCd = 1; // 채권처리구분(1:신청,2:접수)
scwin.vDtlInfoRowCount = 0;
scwin.vViewYN = 'Y';
scwin.pIsurCd = '';
scwin.arrPar = new Array();
scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        $c.bns.BnsPanelToGroupBox(pnl_Req); // 패널라운드처리(신청)
        $c.bns.BnsPanelToGroupBox(pnl_DtlInfo); // 패널라운드처리(상세)
        $c.bns.BnsPanelToGroupBox(pnl_Acpt); // 패널라운드처리(접수)

        tab_List.setSelectedTabIndex(1);

        // 콤보데이터 설정
        scwin.setComboCode();
        scwin.setParam(); // 호출파라미터설정
        scwin.dtlSync(); // 상세조회

        // 채권신고담당자 조회
        scwin.search2();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS90018.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name tab_List_OnSelChanged
 * @description tab List On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {void}
 * @hidden N
 */
scwin.tab_List_OnSelChanged = function(nIndex) {
    try {
        scwin.vBndListProcsTpCd = nIndex;
        scwin.dtlSync(); // 상세조회

        // 채권신고담당자 조회
        scwin.search2();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS90018.tab_List_OnSelChanged" });
    }
};

/**
 * @method
 * @name dts_DtlInfo_OnLoadCompleted
 * @description dts_DtlInfo 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_DtlInfo_OnLoadCompleted = function(rowcount) {
    try {
        scwin.vDtlInfoRowCount = rowcount;
        scwin.chgBndList(); // 종목명 회차 조회
        scwin.isuCdCombo(); // 종목기준명 콤보데이터 설정
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS90018.dts_DtlInfo_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name img_StrtDd_onclick
 * @description img_StrtDd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_StrtDd_onclick = function() {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        popUpCalendar2(edt_StrtDd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS90018.img_StrtDd_onclick" });
    }
};

/**
 * @method
 * @name btn_Attach_onclick
 * @description 「첨부파일확인」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Attach_onclick = async function() {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        if ("N" === dts_DtlInfo.getCellData(1, "HAS_ATTACH_DOC")) {
            await $c.win.alert("연결된 팩스/첨부문서가 없습니다.");
            return;
        }
        scwin.fn_GetPar = scwin.getCommonKey;
        $c.bns.fn_PopAttachDocSearch(lbl_BndApplId);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS90018.btn_Attach_onclick" });
    }
};

/**
 * @method
 * @name cmb_BndClssCd_onselchange
 * @description cmb_BndClssCd onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_BndClssCd_onselchange = function() {
    try {
        /** 채권분류 적용 */
        dts_IsuList.setBroadcast(false);
        for (let i = 1; i <= dts_IsuList.getRowCount(); i++) {
            dts_IsuList.setCellData(i, "AFCHG_BND_CLASS_CD", cmb_BndClssCd.getValue());
        }
        dts_IsuList.setBroadcast(true, true);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS90018.cmb_BndClssCd_onselchange" });
    }
};

/**
 * @method
 * @name cmb_BndTpCd_onselchange
 * @description cmb_BndTpCd onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_BndTpCd_onselchange = function() {
    try {
        /** 채권유형 적용 */
        dts_IsuList.setBroadcast(false);
        for (let i = 1; i <= dts_IsuList.getRowCount(); i++) {
            dts_IsuList.setCellData(i, "AFCHG_BND_TP_CD", cmb_BndTpCd.getValue());
        }
        dts_IsuList.setBroadcast(true, true);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS90018.cmb_BndTpCd_onselchange" });
    }
};

/**
 * @method
 * @name cmb_IsuNm_onselchange
 * @description cmb_IsuNm onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_IsuNm_onselchange = function() {
    try {
        /** 종목기준명 적용 */
        const vIdx = cmb_IsuNm.getSelectedIndex() + 1;
        dts_IsuList.setBroadcast(false);
        for (let i = 1; i <= dts_IsuList.getRowCount(); i++) {
            dts_IsuList.setCellData(i, "AFCHG_ISU_NM", dts_IsuSelList.getCellData(vIdx, "TEXT"));
            dts_IsuList.setCellData(i, "AFCHG_ISU_ABBRV", dts_IsuSelList.getCellData(vIdx, "TEXT2"));
            dts_IsuList.setCellData(i, "AFCHG_ISU_ENG_NM", dts_IsuSelList.getCellData(vIdx, "TEXT3"));
            dts_IsuList.setCellData(i, "AFCHG_ISU_ENG_ABBRV", dts_IsuSelList.getCellData(vIdx, "TEXT4"));
        }
        dts_IsuList.setBroadcast(true, true);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS90018.cmb_IsuNm_onselchange" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS90018.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name dts_BndTpCd_OnLoadCompleted
 * @description dts_BndTpCd 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_BndTpCd_OnLoadCompleted = function(rowcount) {
    try {
        // 채권유형 공백란 추가
        dts_BndTpCd.insertRow(dts_BndTpCd.getRowPosition() - 1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS90018.dts_BndTpCd_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_IsuSelList_OnLoadCompleted
 * @description dts_IsuSelList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_IsuSelList_OnLoadCompleted = function(rowcount) {
    try {
        if (scwin.vBndListProcsTpCd === 2) {
            const vCmbRow = $c.cp.getNameValueRow(dts_IsuSelList, "TEXT", dts_IsuList.getCellData(1, "AFCHG_ISU_NM"));
            cmb_IsuNm.setSelectedIndex(vCmbRow - 1);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS90018.dts_IsuSelList_OnLoadCompleted" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setParam
 * @description 부모창에서 받은 데이터를 설정한다.
 * @returns {void}
 * @hidden N
 */
scwin.setParam = function() {
    const prt = $c.frame.path("../");
    if (prt !== undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
        scwin.fn_SetPar = prt.scwin.fn_SetPar;
    }
    if (scwin.fn_GetPar !== undefined) {
        scwin.fn_GetPar(scwin.arrPar);
        scwin.pBndApplId = scwin.arrPar[0].BND_APPL_ID;
        scwin.pIsurCd = scwin.arrPar[0].ISUR_CD;
    }
};

/**
 * @method
 * @name dtlSync
 * @description 상세조회
 * @returns {void}
 * @hidden N
 */
scwin.dtlSync = function() {
    let dsNm = 'BNS_CHG_BND_INFO';
    let qryId = 'lds.stf.bnschg.select.readChgBndInfo_202';
    let param = '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.vBndListProcsTpCd;
    param += '&{P}V_MKTACT_CD=' + scwin.vMktactCd;
    param += '&{P}V_BND_APPL_ID=' + scwin.pBndApplId;
    param += '&{P}V_VIEW_YN=' + scwin.vViewYN;
    $c.bns.fn_SearchBns('ULDBNS90018.xml', dts_DtlInfo, dsNm, qryId, param);
};

/**
 * @method
 * @name chgBndList
 * @description 합병/회사분할 회차 종목 조회
 * @returns {void}
 * @hidden N
 */
scwin.chgBndList = function() {
    let dsNm = 'BNS_CHG_BND_LIST';
    let qryId = 'lds.stf.bnschg.select.readChgBndIsuInfo_202';
    let param = '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.vBndListProcsTpCd;
    param += '&{P}V_BND_APPL_ID=' + scwin.pBndApplId;
    param += '&{P}V_VIEW_YN=' + scwin.vViewYN;
    dts_IsuList.SyncLoad = true;
    $c.bns.fn_SearchBns('ULDBNS90018.xml', dts_IsuList, dsNm, qryId, param);
};

/**
 * @method
 * @name search2
 * @description 채권신고담당자 조회
 * @returns {void}
 * @hidden N
 */
scwin.search2 = function() {
    dts_List3.removeAll();
    let dsNm = 'BNS_BND_DECL_CHRG_LIST';
    let qryId = 'lds.stf.bnsdecl_mgr.select.selectBndDeclChrgList';
    let param = '&{P}V_ISUR_CD=' + scwin.pIsurCd;
    $c.bns.fn_SearchBns('ULDBNS90018.xml', dts_List3, dsNm, qryId, param);
};

/**
 * @method
 * @name isuCdCombo
 * @description 종목기준명 콤보 데이터 조회
 * @returns {void}
 * @hidden N
 */
scwin.isuCdCombo = function() {
    let param = "&{P}V_ISUR_CD=" + dts_DtlInfo.getCellData(1, "ISUR_CD");
    let dsNm = 'BNS_ISU_CD';
    let qryId = 'lds.stf.bnschg.select.listIsuBasNm';
    $c.bns.fn_SearchBns('ULDBNS90018.xml', dts_IsuSelList, dsNm, qryId, param);
};

/**
 * @method
 * @name setComboCode
 * @description 콤보데이터 정의 (채권유형코드)
 * @returns {void}
 * @hidden N
 */
scwin.setComboCode = function() {
    let dsNm = 'BNS_COM_CD';
    let qryId = 'lds.stf.bnscommon.select.selectBndClss';
    let param = '';
    $c.bns.fn_SearchBns('ULDBNS90018.xml', dts_BndClassCd, dsNm, qryId, param);
    $c.bns.fn_SetBnsCombo('ULDBNS90018.xml', dts_BndTpCd, '01422');
};

/**
 * @method
 * @name getCommonKey
 * @description 팝업에 넘길 키데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getCommonKey = function(arrPar) {
    scwin.arrPar[0] = {
        // 첨부문서 목록 팝업
        BND_APPL_ID: dts_DtlInfo.getCellData(1, "BND_APPL_ID"),
        BND_LIST_PROCS_TP_CD: dts_DtlInfo.getCellData(1, "BND_LIST_PROCS_TP_CD"),
        ISU_CD: dts_DtlInfo.getCellData(1, "ISU_CD")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    scwin.arrPar, length;
};

/**
 * @method
 * @name getBasNm
 * @description 채권기준명 팝업에 넘길 키데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getBasNm = function(arrPar) {
    scwin.arrPar[0] = {
        ISUR_CD: dts_DtlInfo.getCellData(1, "ISUR_CD"),
        MKTACT_TP_CD: scwin.vMktactCd
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    scwin.arrPar, length;
};

/**
 * @method
 * @name setBasNm
 * @description 채권기준명 팝업에서 받은 데이터를 설정한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setBasNm = function(arrPar) {
    if ("Y" === scwin.arrPar[0].SUCCESS_YN) {
        dts_IsuSelList.Reset();
    }
};
